if(String(env.get("INV1_TRANSPORT")||"").toLowerCase()!=="esp32")return null;
const h=String(env.get("INV1_ESP_HOST")||"");
const p=Number(env.get("INV1_ESP_PORT")||18081);
const code=String(env.get("INV1_ESP_CODE")||"");
if(!/^[a-zA-Z0-9.-]+$/.test(h)||p<1||p>65535||code.length<8)return null;
msg.inverterNum=1;msg.method="GET";
msg.url="http://"+h+":"+p+"/api/v1/bridge/snapshot";
msg.headers={"X-Setup-Code":code,"Accept":"application/json"};
delete msg.payload;return msg;

const inv=1;
if(String(env.get("INV"+inv+"_TRANSPORT")||"").toLowerCase()!=="esp32")return null;
const offline={topic:"voltronic/"+inv+"/availability",payload:"offline",retain:true};
let d=msg.payload;
if(typeof d==="string"){try{d=JSON.parse(d);}catch(e){d=null;}}
if(msg.error||msg.statusCode!==200||!d||d.cache_only!==true||d.available!==true||!Array.isArray(d.replies))return [null,offline];
const uptime=Number(d.uptime_ms),max=Number(d.max_seq);
if(!Number.isFinite(uptime)||!Number.isFinite(max))return [null,offline];
let seen=context.get("seen")||{},prev=context.get("uptime")||0;
if(uptime<prev)seen={};
context.set("uptime",uptime);
let emitted=[];
function crc16(bytes){let c=0;for(const b of bytes){c^=b<<8;for(let j=0;j<8;j++)c=(c&32768)?(((c<<1)^0x1021)&65535):((c<<1)&65535);}return c;}
const utc=new Date().toISOString().slice(0,10).replace(/-/g,"");
for(const r of d.replies.slice().sort((a,b)=>Number(a.seq)-Number(b.seq))){
 const cmd=String(r.command||"").toUpperCase(),seq=Number(r.seq),age=Number(r.age_ms);
 if(!/^(QPIGS2?|QMOD|QPIRI|QDOP|QPIWS|QMN|QID|QVFW3?|QBMS|Q1|QET|QLT|QED[0-9]{8}|QLD[0-9]{8}|QEM[0-9]{6}|QLM[0-9]{6}|QEY[0-9]{4}|QLY[0-9]{4})$/.test(cmd))continue;
 if(!Number.isSafeInteger(seq)||seq<=0||seq>max||seq<=(seen[cmd]||0))continue;
 const ttl=cmd==="QPIGS"?10000:cmd==="QPIGS2"?15000:/^(QMOD|QPIRI|QDOP|QPIWS)$/.test(cmd)?900000:90000000;
 if(!Number.isFinite(age)||age<0||age>ttl)continue;
 if(/^Q[EL][DMY][0-9]+$/.test(cmd)){
  const key=cmd.slice(3),expected=cmd[2]==="D"?utc:cmd[2]==="M"?utc.slice(0,6):utc.slice(0,4);
  if(key!==expected)continue;
 }
 let buffer;
 if(r.nak===true)buffer=Buffer.from([0x15]);
 else{
  const payload=String(r.payload||"");
  if(!payload||payload.length>440||/[^\x20-\x7e]/.test(payload))continue;
  const body=Buffer.from("("+payload,"ascii"),crc=crc16(body);
  buffer=Buffer.concat([body,Buffer.from([crc>>8,crc&255,13])]);
 }
 seen[cmd]=seq;
 emitted.push({inverterNum:inv,_esp_bridge:true,_esp_command:cmd,_esp_seq:seq,payload:buffer});
}
context.set("seen",seen);
return [emitted,{topic:"voltronic/"+inv+"/availability",payload:"online",retain:true}];

